 const KEYS_PT={reserve:/guardad[oa]s?|guarde menos|reserva/i,capital:/dinheiro que voc[êe] tem|dinheiro dispon[íi]vel|j[áa] tenho|dinheiro insuficiente|n[ãa]o tem dinheiro suficiente/i,extra:/ganh[a-z]* a mais|rend[a-z]* a mais|a mais por hora|quer a mais/i,hourly:/por hora|voc[êe] ganhar?\b|\bganha\b/i,target:/objetivo|quero ter|quer ter|quantia que voc[êe] quer/i,price:/pre[çc]o|\bcusta/i,daily:/por dia|di[áa]ri/i,minutes:/minutos|dura[çc][ãa]o da sess[ãa]o|tempo dispon[íi]vel|pr[óo]xima sess[ãa]o/i,players:/jogadores/i,hours:/dura[çc][ãa]o em horas|voc[êe] usar?\b|horas de uso/i,days:/dias por semana/i,upkeep:/gastos por sess[ãa]o/i,units:/[ée] preciso chegar a/i};
 if(h.E&&h.E.lang==='pt')KEYS.forEach(k=>{k[1]=new RegExp(k[1].source+'|'+KEYS_PT[k[0]].source,'i');});
