  if(tool==='plan'){const m=/^(?:Mission|Misión|Missione|Missão) (\d+)/.exec(reason||'');if(m){const id='plan-m-'+(Number(m[1])-1)+'-'+(/dur[ée]e|duration|duraci[óo]n|durata|dura[çc][ãa]o/i.test(reason)?'duration':/frais|co[ûu]ts|fees|costs|gastos|costes|spese|costi|custos/i.test(reason)?'cost':'reward');if($(id))return '<p class="b-problem">'+btn('Ir para o campo a corrigir','data-b-focus="'+id+'"')+'</p>';}}
