 function hypothesesBlock(){const an=state().analysis;return '<details class="calc-optional b-hypotheses b-expert" id="calc-hypotheses"><summary>Minhas hipóteses: combustível, manutenção, munição, tentativas fracassadas</summary><p class="calc-note"><b>Alcance:</b> essas hipóteses contam nos oito cálculos. O plano de negócios tem os próprios campos; ele só pega a munição simulada, somada aos gastos de cada tentativa de missão. Nenhuma dessas mecânicas está confirmada no GTA VI: nada é contado sem a sua escolha, e um número escolhido continua marcado como “simulação” em todo lugar, até nos seus cálculos salvos. Se você mesmo escrever o custo por sessão de uma compra, a simulação não é somada a ele.</p>'+SIMS.map(([k,label,fields])=>'<fieldset class="b-sim-item"><legend>'+check('analysis.simulations.'+k,label,an.simulations[k])+'</legend><div class="calc-fields" data-sim-fields="'+k+'" '+(an.simulations[k]?'':'hidden')+'>'+fields.map(([f,l])=>field('analysis.sim.'+k+'.'+f,l,an.sim[k][f],{id:'sim-'+k+'-'+f,max:k==='echec'?10:1e12,integer:k==='echec'})).join('')+'</div></fieldset>').join('')+'<p class="calc-note">Combustível: distância × consumo ÷ 100 × preço do litro = custo por sessão.</p></details>';}
