 return field('goal.players','Quantos jogadores somos, eu incluído?',s.goal.players,{id:'roi-players',min:1,max:100,integer:true})+'<fieldset class="b-roi-activities"><legend>Quais atividades combinam com esta compra?</legend>'+all.map(x=>{const canonical=item?.activityIds?.includes(x.id)||x.purchaseIds?.includes(item?.id);return '<label class="calc-check"><input type="checkbox" data-b-roi-activity="'+esc(x.id)+'" '+(r.activityIds.includes(x.id)?'checked':'')+'>'+esc(x.name)+' · '+(canonical?'vínculo conhecido pelo site':'quem diz sou eu')+'</label>';}).join('')+'</fieldset><p class="calc-note">Esse vínculo quem diz é você. As atividades são feitas uma depois da outra: você paga os gastos antes e recebe a recompensa depois. O preço da compra substitui o que é preciso comprar antes de começar, para não contar duas vezes.</p>'+inlineActivities('roi',null);
