 function orderItems(){const s=state();if(!s.order.keys.length)return '<p class="calc-empty">Adicione a sua primeira compra. Um preço que falta continua desconhecido.</p>';return s.order.keys.map((key,index)=>{const a=lookup(key);if(!a)return warning('Compra ausente: '+key)+btn('Parar de comparar','data-b-order-remove="'+esc(key)+'"');const i=s.assets.indexOf(a),item=itemFor(a);return '<article class="b-order-item" data-b-order-key="'+esc(key)+'"><div class="b-order-head">'+media(item)+'<div><strong>'+esc((index+1)+'. '+a.name)+'</strong><p>'+esc(labels[item?.type]||'Compra livre')+' · '+orderPrice(a)+'</p></div></div><div class="b-order-actions">'+btn('↑','data-b-order-up="'+esc(key)+'" aria-label="Subir '+esc(a.name)+'" '+(index===0?'disabled':''))+btn('↓','data-b-order-down="'+esc(key)+'" aria-label="Descer '+esc(a.name)+'" '+(index===s.order.keys.length-1?'disabled':''))+btn('Editar','data-b-order-edit="'+esc(key)+'" aria-expanded="'+(orderEditor===key)+'"')+btn('Remover','data-b-order-remove="'+esc(key)+'"')+'</div><div '+(orderEditor===key?'':'hidden')+' class="b-order-editor">'+(!a.itemId?field('assets.'+i+'.name','Nome desta compra',a.name,{type:'text'}):'')+priceField(key,'order-price-'+index)+'<div class="b-expert">'+field('assets.'+i+'.extras','Gastos e melhorias ($)',a.extras)+field('assets.'+i+'.fees','Outros gastos no início ($)',a.fees)+select('assets.'+i+'.incomeMode','O que eu ganho depois desta compra',[['none','Nenhuma renda extra'],['personal','Sim, mais ou menos este valor por hora (eu escrevo)'],['roi','Resultado vinculado de Vale a pena?']],a.incomeMode,false,'order-assets-'+i+'-incomeMode')+field('assets.'+i+'.boostHourly','Ele me faz ganhar a mais ($ por hora)',a.boostHourly,{hint:'Só se esse dinheiro realmente se somar ao que você já ganha. O jogo não promete nada.'})+'<label class="calc-check"><input type="checkbox" data-b-owned="'+esc(key)+'" '+(a.owned?'checked':'')+'> Compra já obtida (pré-requisito da atividade atendido)</label>'+usageField(i,a,'order-usage-'+index)+(s.order.keys.length>1?'<fieldset class="b-requires"><legend>Comprar antes dele (se for obrigatório)</legend>'+s.order.keys.filter(k=>k!==key).map(k=>{const o=lookup(k);return o?'<label class="calc-check"><input type="checkbox" data-b-requires="'+esc(key)+'|'+esc(k)+'" '+((a.requires||[]).includes(k)?'checked':'')+'> '+esc(o.name)+'</label>':'';}).join('')+'<p class="calc-note">Marque só se o jogo realmente exigir (por exemplo, uma melhoria que precisa do veículo). A ordem sugerida vai respeitar isso.</p></fieldset>':'')+'</div></div></article>';}).join('')+(lastRemoved?btn('Desfazer a remoção do carrinho','data-b-order-undo="1"'):'');}
