 B.tools.forEach(t=>{const panel=$('panel-'+t);panel.insertAdjacentHTML('afterbegin','<div class="b-mode-summary" id="mode-summary-'+t+'"></div>');panel.insertAdjacentHTML('beforeend','<div class="b-expert calc-card calc-subsection" id="expert-'+t+'"></div><div class="b-stage-actions">'+btn('Ver os ajustes avançados (modo Avançado)','data-b-mode="advanced" data-b-advanced="'+t+'"')+'<span class="b-expert-only">'+btn('Tudo certo nesta etapa ✓','data-b-complete="'+t+'"')+'</span>'+btn('Ir para o meu plano de negócios','data-open="plan"')+'</div>');});
 /* v7.66 : options retirées en v7.47 rendues au mode Expert : les deux blocs « Mes calculs enregistrés » / « Mes business plans » du bas de page (ils ouvrent le tiroir sur la bonne liste) */
 /* v7.71 : le bloc vit hors de #calc-panels, que mount() vide à chaque restauration (calcul rechargé, lien, Léo) : l'ancien est retiré avant d'écrire le nouveau (il était dupliqué) */
