   const gp=B.goalPurchase&&a?B.goalPurchase(s,sourceActivities,ctx(),a.key):null,gpOk=!!(gp&&gp.valid&&gp.buy&&gp.buy.state==='ok'&&gp.save&&gp.save.hours!==null&&gp.delayHours!==null);
   const delay=gpOk?(gp.delayHours>1e-9?gp.delayHours:null):q.valid&&q.goalDelayHours!==null&&q.goalDelayHours>0?q.goalDelayHours:null;
