   const answer=short?'Ainda não: falta <b>'+money(d.shortfall)+'</b> para '+esc(name)+', sem mexer no dinheiro guardado.':(named?'Sim, você pode comprar '+esc(name)+'.':'Sim, você pode comprar.')+' Você ficaria com <b>'+money(d.cashRemaining)+'</b>, dos quais '+money(s.goal.reserve)+' guardados.'+(d.remaining===0?' Isso usa tudo o que você pode gastar.':'');
   const netOk=own,waitH=own?(gp.hourlyNet>0&&Number.isFinite(gp.affordHours)?gp.affordHours:null):d.waitHours;
