  if(t==='session')return [['Tempo para jogar',hours(s.session.minutes/60)],['Atividades marcadas',nf.format(s.session.enabled.length)],['Tenho',cash(g.capital)]];
  if(t==='activities')return [['Atividade',activityName(s,s.inverse.selected)],['Tempo para jogar',hours(s.inverse.minutes/60)],['Tenho',cash(g.capital)]];
