  setHTML($('saved-list'),(drawerView==='calcs'?undo:'')+(calcs.length?calcs.map(e=>entryCard(e,'calc')).join(''):'<div class="calc-empty b-saved-empty"><p><b>Nada salvo por enquanto.</b></p><p>Faça um cálculo e toque em “☆ Salvar este cálculo”. Ele fica guardado aqui, com a data e a resposta.</p></div>'));
  setHTML($('saved-plans-list'),(drawerView==='plans'?undo:'')+(plans.length?plans.map(e=>entryCard(e,'plan')).join(''):'<div class="calc-empty b-saved-empty"><p><b>Nenhum plano de negócios salvo.</b></p><p>Em “Meu plano de negócios”, toque em “☆ Salvar o plano”. Ele fica guardado aqui, com a ficha.</p>'+btn('Abrir meu plano de negócios','data-drawer-close="1" data-open="plan"')+'</div>'));
  const known=new Set([...calcs,...plans].map(e=>e.id));picked=picked.filter(id=>known.has(id));for(const id of [...cardCache.keys()])if(!known.has(id))cardCache.delete(id);
  document.querySelectorAll('[data-b-pick]').forEach(i=>{i.checked=picked.includes(i.dataset.bPick);i.closest('.b-notebook-entry')?.classList.toggle('is-picked',i.checked);});
