 document.querySelectorAll('[data-field]:not([type=checkbox])').forEach(el=>{let v=s;for(const k of el.dataset.field.split('.'))v=v?.[k];if(el===document.activeElement||v===undefined)return;const P=global.LKCalcEngine&&global.LKCalcEngine.parseLocalizedNumber;const cur=el.dataset.number&&P?P(el.value).value:el.value;if(el.dataset.number?(cur!==v&&!(v===null&&el.value.trim()===''))&&String(cur)!==String(v):String(el.value)!==String(v??''))el.value=v??'';});
