 document.querySelectorAll('[data-b-roi-activity]').forEach(el=>{const a=all.find(x=>x.id===el.dataset.bRoiActivity);if(a&&el.nextSibling)el.nextSibling.textContent=a.name+' · '+(roiItem?.activityIds?.includes(a.id)||a.purchaseIds?.includes(roiItem?.id)?'vínculo conhecido pelo site':'quem diz sou eu');el.checked=s.roi.activityIds.includes(el.dataset.bRoiActivity);});
