 function pathValue(o,path){let v=o;for(const k of path.split('.'))v=v?.[k];return v;}
 function isExampleField(s,fieldId){const el=fieldId&&$(fieldId);if(!el||!el.dataset.field)return false;const v=pathValue(s,el.dataset.field),d=pathValue(api.initial,el.dataset.field);return v!==null&&v!==undefined&&v!==''&&JSON.stringify(v)===JSON.stringify(d);}
 /* Tout l’outil est encore à l’état de l’exemple : ses réglages propres (achats, panier, missions…) sont ceux du départ. */
