 function markExamples(s){document.querySelectorAll('.b-explain').forEach(box=>{let total=0,ex=0;box.querySelectorAll('.b-assumptions li').forEach(li=>{const b=li.querySelector('[data-b-focus]'),or=li.querySelector('.b-origin');if(!b)return;total++;if(isExampleField(s,b.dataset.bFocus)){ex++;if(or&&or.classList.contains('b-o-toi')){or.className='b-origin b-o-ex';or.textContent='exemplo';}li.classList.add('is-example');}});
   const panel=box.closest('.calc-result')||box.closest('.calc-card');const tag=panel&&[...panel.querySelectorAll('.calc-tag')].find(x=>/TES CHIFFRES|YOUR NUMBERS|TUS CIFRAS|I TUOI NUMERI|DEINEN ZAHLEN|DEINE ZAHLEN/.test(x.textContent));if(tag&&total&&ex===total&&exampleState(s,box.dataset.explain)){tag.textContent=tag.textContent.replace('SEUS NÚMEROS','OS EXEMPLOS');tag.title='Os números ainda são os do exemplo: troque-os pelos seus.';tag.classList.add('is-example');}});}
