 function search(el){combo=el;comboIndex=-1;const q=el.value;comboRows=choices.filter(x=>api.searchMatch(x,q)).slice(0,12);const list=$(el.id+'-list');list.innerHTML=comboRows.map((x,i)=>'<div class="b-suggestion" role="option" id="'+el.id+'-option-'+i+'" aria-selected="false" data-b-suggestion="'+i+'">'+media(x)+'<span><strong>'+esc((x.brand?x.brand+' ':'')+x.name)+'</strong><small>'+esc(labels[x.type]||x.category)+' · '+(x.price===null?'preço desconhecido':money(x.price))+'</small></span></div>').join('');list.hidden=!comboRows.length;el.setAttribute('aria-expanded',String(!!comboRows.length));el.removeAttribute('aria-activedescendant');$(el.id+'-feedback').textContent=comboRows.length?comboRows.length+' sugestão(ões), use as setas e depois Enter para escolher.':'Nenhuma compra correspondente no catálogo.';}
