 function selectSuggestion(index){const item=comboRows[index];if(!item||!combo)return;const context=combo.dataset.bCombo,id=combo.id,s=state();let a=null;if(context!=='plan'&&context!=='plan-prereq'){try{a=B.addAsset(s,item);}catch(e){api.notify(e.message);return;}}closeCombo();if(context==='compare'){if(!s.compare.keys.includes(a.key)){if(s.compare.keys.length>=6){api.notify('No máximo seis compras na comparação.');return;}s.compare.keys.push(a.key);}}else if(context==='plan'){s.plan.goal={...s.plan.goal,kind:'purchase',name:item.name,itemId:item.id,referencePrice:item.price,price:item.price};s.plan.variant='auto';}else if(context==='plan-prereq'){if(s.plan.prerequisites.length>=20){api.notify('No máximo vinte compras anteriores.');return;}if(!s.plan.prerequisites.some(x=>x.itemId===item.id))s.plan.prerequisites.push({id:'p-'+Date.now().toString(36)+'-'+s.plan.prerequisites.length,name:item.name,itemId:item.id,referencePrice:item.price,price:item.price,boostHourly:0,owned:false});s.plan.variant='auto';}else if(context==='roi-compare'){s.roi.compareKey=a.key;}else if(context==='roi'){s.roi.key=a.key;s.purchase.key=a.key;s.roi.activityIds=B.activities(s,sourceActivities).filter(x=>item.activityIds.includes(x.id)||x.purchaseIds?.includes(item.id)).map(x=>x.id);}else{if(!s.order.keys.includes(a.key))s.order.keys.push(a.key);orderEditor=a.key;}s.completed=[];refresh(context==='roi'?'f-roi-purchase':context==='plan'?'plan-price':context==='plan-prereq'?'plan-p-'+(s.plan.prerequisites.length-1)+'-price':id);api.notify(item.name+' selecionado. '+(item.price===null?'Informe o preço que você imagina.':'O preço do catálogo está disponível.'));}
 function copyToPlanGoal(s,a,boost){const item=itemFor(a);s.plan.goal={...s.plan.goal,kind:'purchase',name:a.name,itemId:a.itemId||'',referencePrice:item?item.price:null,price:a.price===null?null:a.price+(a.extras||0)+(a.fees||0),boostHourly:Number.isFinite(boost)?Math.max(0,boost):0};s.plan.variant='auto';}
